// ==================== 服务定义 ====================
//
// ⚠️ 站级公开公告（/api/v1/notifies/public）**不在本文件**：见 common.thrift 的
// 「站级公开公告」段——它必须挂在一个 /api 组不带鉴权的 IDL 域下（本域的 /api 组
// 挂了 UserOrAPIKey，公开端点落进来就会被误加登录门槛）。
type NotifyService interface {
	// List 通知列表（管理）
	List(ctx context.Context, req *ListReq) (r *ListResp, err error)
	// Active 当前活跃通知（公开）
	Active(ctx context.Context, req *ActiveReq) (r *ActiveResp, err error)
	// Get 获取单条
	Get(ctx context.Context, req *GetReq) (r *GetResp, err error)
	// Create 创建
	Create(ctx context.Context, req *CreateReq) (r *CreateResp, err error)
	// Update 更新
	Update(ctx context.Context, req *UpdateReq) (r *UpdateResp, err error)
	// Delete 删除
	Delete(ctx context.Context, req *DeleteReq) (r *DeleteResp, err error)
	// ==================== 我的通知（2026-10-09 IDL 化；认证=JWT/API Key 二选一） ====================
	// Mine 我的通知列表（含广播 + 定向）
	Mine(ctx context.Context, req *MineReq) (r *MineResp, err error)
	// UnreadCount 未读数（未登录防御性返回 0——历史语义，路由层实际拦截）
	UnreadCount(ctx context.Context, req *MineReq) (r *UnreadCountResp, err error)
	// MarkRead 标记已读（当前仅支持 all=true）
	MarkRead(ctx context.Context, req *MarkReadReq) (r *MarkReadResp, err error)
}

